import{_ as t,o as s,c as a,a3 as n}from"./chunks/framework.BlfGB29P.js";const i="/eep/ini-edit-translate-2026/editor-fr.png",f=JSON.parse('{"title":"INI Edit Translate 2026","description":"Fonctions de l’éditeur Windows de fichiers INI de modèles EEP et d’Installation.eep avec traduction ChatGPT.","frontmatter":{"title":"INI Edit Translate 2026","description":"Fonctions de l’éditeur Windows de fichiers INI de modèles EEP et d’Installation.eep avec traduction ChatGPT."},"headers":[],"relativePath":"fr/eep/ini-edit-translate-2026/index.md","filePath":"fr/eep/ini-edit-translate-2026/index.md","lastUpdated":1792754181000}'),r={name:"fr/eep/ini-edit-translate-2026/index.md"};function o(d,e,l,c,u,p){return s(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="ini-edit-translate-2026" tabindex="-1">INI Edit Translate 2026 <a class="header-anchor" href="#ini-edit-translate-2026" aria-label="Permalink to &quot;INI Edit Translate 2026&quot;">​</a></h1><p><strong>Version 2.1.35.0 · Windows 11 · .NET Framework 4.8</strong></p><p>Modifier les descriptions de modèles EEP et leurs fichiers d’installation. Développé par Uwe Grimm / UGSo Software et publié sous licence MIT.</p><p><a href="https://github.com/rockbaer2007/ini-edit-translate-2026" target="_blank" rel="noreferrer">Code source et README sur GitHub</a></p><p><img src="'+i+'" alt="Interface française vérifiée, sans données personnelles"></p><h2 id="fonctions" tabindex="-1">Fonctions <a class="header-anchor" href="#fonctions" aria-label="Permalink to &quot;Fonctions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Domaine</th><th>Possibilités</th></tr></thead><tbody><tr><td>Textes de modèles</td><td>Modifier les noms et descriptions en EN/DE/FR/PL</td></tr><tr><td>Métadonnées</td><td>Modifier les références PDF, génération, années d’utilisation, pays et icône</td></tr><tr><td>Axes de mouvement et fonctions des signaux</td><td>Afficher, modifier et traduire les entrées par langue</td></tr><tr><td>Installation.eep</td><td>Modifier les noms et descriptions des sections d’installation prises en charge</td></tr><tr><td>Aperçu</td><td>Comparer le fichier original à l’aperçu du résultat</td></tr><tr><td>Export des tableaux</td><td>Export complet en UTF-8 avec BOM et séparateurs de tabulation</td></tr><tr><td>Sauvegardes</td><td>Copier les fichiers INI existants avant remplacement, en conservant leur nom d’origine</td></tr></tbody></table><h2 id="traduction-chatgpt" tabindex="-1">Traduction ChatGPT <a class="header-anchor" href="#traduction-chatgpt" aria-label="Permalink to &quot;Traduction ChatGPT&quot;">​</a></h2><p>L’application utilise uniquement l’API OpenAI Responses. Chaque texte source est traduit vers les trois autres langues dans une seule requête, sans passer par une traduction intermédiaire anglaise. Un cache temporaire évite les répétitions au sein d’une même opération.</p><p>La fenêtre de progression propose <strong>Annuler</strong>. Le délai est de 60 secondes et la limite de 24 000 caractères par texte. Les réponses incomplètes, langues manquantes et espaces réservés modifiés, tels que <code>{0}</code>, <code>%s</code> ou <code>[e]</code>, sont rejetés. Les textes et tableaux existants sont conservés en cas d’échec.</p><p>Les textes DE/EN/FR ont été révisés : caractères endommagés, mauvaises langues et messages mélangés. Les clés INI techniques telles que <code>Name_GER</code> sont conservées.</p><h2 id="installation-et-utilisation" tabindex="-1">Installation et utilisation <a class="header-anchor" href="#installation-et-utilisation" aria-label="Permalink to &quot;Installation et utilisation&quot;">​</a></h2><ol><li>Compiler avec Visual Studio 2026, le développement de bureau .NET et le Developer Pack .NET Framework 4.8. Les commandes figurent dans la README.</li><li>Lancer <code>INI Edit Translate 2026.exe</code> depuis Release en conservant ses DLL et dossiers de langues.</li><li>Ouvrir <strong>À propos → Paramètres → Traduction OpenAI</strong> et saisir sa propre clé API et le modèle ; <code>gpt-4.1-mini</code> par défaut.</li><li>Ouvrir d’abord une copie sauvegardée en mode <strong>Lecture seule</strong>.</li><li>Utiliser <strong>Lire et traduire</strong> ou un bouton de traduction. Choisir la langue source des axes et fonctions des signaux.</li><li>Vérifier l’aperçu et les textes, puis enregistrer explicitement.</li></ol><h2 id="donnees-et-confidentialite" tabindex="-1">Données et confidentialité <a class="header-anchor" href="#donnees-et-confidentialite" aria-label="Permalink to &quot;Données et confidentialité&quot;">​</a></h2><p>Les anciennes inscriptions et bases personnelles ne sont pas importées. Les paramètres sont séparés par utilisateur Windows. La configuration OpenAI et les sauvegardes sont conservées sous <code>%LOCALAPPDATA%/UGSo/IET2026/</code>.</p><p>Windows DPAPI chiffre la clé API pour le compte Windows actuel. Les textes sélectionnés sont envoyés à OpenAI avec <code>store: false</code>. Internet et une facturation API distincte sont nécessaires ; un abonnement ChatGPT ne remplace pas cette facturation.</p><h2 id="mise-a-jour-et-verifications" tabindex="-1">Mise à jour et vérifications <a class="header-anchor" href="#mise-a-jour-et-verifications" aria-label="Permalink to &quot;Mise à jour et vérifications&quot;">​</a></h2><p><strong>La mise à jour est entièrement désactivée</strong> : aucune connexion à l’ancien serveur et aucun menu de mise à jour. Google, LEO, Linguee et DeepL ne sont plus proposés.</p><p>30 contrôles locaux avec réponses API simulées et les compilations Debug/Release vérifient les erreurs, l’annulation, la restauration, l’export et les interfaces rendues DE/EN/FR. Aucun texte n’est envoyé à OpenAI pendant les tests. Un appel API réel et la qualité des traductions produites restent à vérifier avec son propre compte. Tous les schémas INI possibles ne sont pas pris en charge ; vérifier les données obtenues.</p>',19)])])}const h=t(r,[["render",o]]);export{f as __pageData,h as default};
